const p = $json.body.object.properties;
const alert = p.alerts?.[0]?.properties ?? {};
const ent = p.relatedEntities ?? [];

return [{ json: {
  incident_number: p.incidentNumber,
  title: p.title,
  description: p.description,
  severity: p.severity,
  first_activity: p.firstActivityTimeUtc,
  last_activity: p.lastActivityTimeUtc,
  tactics: p.additionalData?.tactics ?? [],
  techniques: p.additionalData?.techniques ?? [],
  target_host: ent.find(e => e.kind === 'Host')?.properties?.hostName ?? null,
  source_ip: ent.find(e => e.kind === 'Ip')?.properties?.address ?? null,
  link: alert.alertLink ?? p.incidentUrl,
}}];

parameters.text:
={{ (() => {
const e = s => String(s ?? '-').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const o = $json.output;
const d = $('Incident Summary').item.json;
return '🛡️ <b>SIEM #' + e(d.incident_number) + ' — ' + e(d.title) + '</b>\n'
 + 'Severity: ' + e(d.severity) + ' | AI risk: <b>' + e(o.risk) + '</b>\n'
 + 'Host: ' + e(d.target_host) + ' | Source IP: <code>' + e(d.source_ip) + '</code>\n'
 + 'MITRE: ' + e((d.techniques || []).join(', ')) + '\n\n'
 + e(o.summary) + '\n\n'
 + '<b>Likely cause:</b> ' + e(o.likely_cause) + '\n'
 + '<b>Recommended actions:</b>\n'
 + (o.recommended_actions || []).map(a => '• ' + e(a)).join('\n') + '\n\n'
 + '<a href="' + e(d.link) + '">Open in Defender</a>';
})() }}

